class Range {
    private volatile int low = 0;
    private volatile int high = 10;

    void setBounds(int l, int h) {
        low = l;
        high = h;
    }

    int span() {
        return high - low;   // read by another thread
    }
}

class Job {
    int processed = 0;                 // plain field
    volatile boolean done = false;     // volatile flag

    void run() {                       // the only worker thread
        for (int i = 0; i < 3; i++) {
            processed++;
        }
        done = true;
    }

    void await() {                     // the main thread
        while (!done) {
            // spin
        }
        System.out.println(processed);
    }
}

practice.code:
class Meter {
    private volatile int hits = 0;
    private volatile boolean started = true;

    void record() {              // called by many threads
        if (started) {
            hits++;
        }
    }
}

class Box { int size = 1; }

// shared
volatile Box box = null;

// writer thread
Box b = new Box();
b.size = 5;
box = b;          // volatile write
b.size = 9;       // later mutation, no synchronization

// reader thread
Box r = box;
if (r != null) {
    System.out.println(r.size);
}
